CameraEditor::~CameraEditor(){cancelBake=true;if(bakeThread.joinable())bakeThread.join();stopCapture();cancelAudio=true;++audioGeneration;if(audioThread.joinable())audioThread.join();}
QString CameraEditor::objectName(int o)const{return o==-1?u("摄像机"):o==-2?u("全画面合成"):QString::fromStdString(layerDisplayName(model->layers.at(size_t(o))));}
QString CameraEditor::objectId(int o)const{if(o<0)return QString::number(o);auto&l=model->layers.at(size_t(o));return QString::fromStdString(l.sceneUuid)+"/"+QString::number(l.itemId)+"/"+QString::fromStdString(l.sourceUuid)+"/"+QString::fromStdString(l.instanceId);}
bool CameraEditor::validParameter(int o,const std::string&p)const{if(o==-2)return p=="sx"||p=="sy"||p=="opacity";if(o==-1)return p!="sx"&&p!="sy"&&p!="opacity";return o>=0&&size_t(o)<model->layers.size()&&(p=="x"||p=="y"||p=="z"||p=="rx"||p=="ry"||p=="rz"||p=="sx"||p=="sy"||p=="opacity");}
void CameraEditor::resetDocument(){cancelBake=true;++bakeGeneration;++editRevision;cancelAudio=true;++audioGeneration;stopCapture();undoStates.clear();redoStates.clear();clipboard.clear();copied.clear();timeline->selection.clear();timeline->candidates.clear();timeline->viewStart=0;timeline->viewSpan=6;identity.clear();active=-1;activeParameter.clear();analysis.reset();candidateStamp.clear();lastEdit.clear();bindingSignature.clear();}
