void CameraEditor::reset(bool all){if(!all&&(active<0||objectLocked(*model,active)))return;size_t layers=0,locked=0,keys=0;for(size_t i=0;i<model->layers.size();++i){if(!all&&int(i)!=active)continue;auto&l=model->layers[i];if(l.locked){++locked;continue;}++layers;for(auto&c:l.animation)keys+=c.second.keys().size();}if(!layers)return;QMessageBox box(QMessageBox::Question,u("确认复位图层"),QString::fromUtf8("将复位 %1 个图层的位置、旋转、缩放与透明度，并删除 %2 个运动关键帧。\n%3 个锁定图层保留。素材、排序和灯光绑定保留。\n是否继续？").arg(layers).arg(keys).arg(locked),QMessageBox::NoButton,this);box.setObjectName("spatial.reset-confirm32");box.addButton(u("取消"),QMessageBox::RejectRole);auto*confirm=box.addButton(u("确认复位"),QMessageBox::AcceptRole);box.setDefaultButton(qobject_cast<QPushButton*>(box.buttons().front()));box.exec();if(box.clickedButton()!=confirm)return;remember();for(size_t i=0;i<model->layers.size();++i){auto&l=model->layers[i];if((!all&&int(i)!=active)||l.locked)continue;l.plane=l.hasDefault?l.defaultPlane:Plane{};l.opacity=l.defaultOpacity;l.orbit={};l.animation.clear();}model->playing=false;timeline->selection.clear();apply();}
